import{_ as t,o,c as r,a5 as a}from"./chunks/framework.BEZBAInb.js";const h=JSON.parse('{"title":"KonadoScript","description":"","frontmatter":{"title":"KonadoScript","order":1},"headers":[],"relativePath":"en/latest/tutorial/script/konado-script.md","filePath":"en/latest/tutorial/script/konado-script.md","lastUpdated":1788455378000}'),i={name:"en/latest/tutorial/script/konado-script.md"};function s(n,e,d,c,l,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="konadoscript" tabindex="-1">KonadoScript <a class="header-anchor" href="#konadoscript" aria-label="Permalink to &quot;KonadoScript&quot;">​</a></h1><p>KonadoScript is an authoring language tailored for visual novels. Its file extension is <code>.ks</code>.</p><p>You can think of it as a more powerful and more structured &quot;novel script&quot;: developers can control story dialogue, character portraits, background switching, music and sound effects, story branches, and choices without writing complex code.</p><h2 id="design-philosophy" tabindex="-1">Design Philosophy <a class="header-anchor" href="#design-philosophy" aria-label="Permalink to &quot;Design Philosophy&quot;">​</a></h2><p>The core design philosophy of KonadoScript is to separate <strong>story content</strong> from <strong>program logic</strong>:</p><ul><li>Writers focus on narrative content without needing programming knowledge</li><li>Programmers focus on engine development without intervening in story creation</li><li>Resource management (images and audio) uses identifiers and is decoupled from scripts</li><li>Modular instruction set, easy to extend with new features</li><li>Compatible with version control systems such as Git</li><li>Text format is naturally cross-platform</li><li>Resource references are platform-independent</li></ul><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="_1-handling-parse-errors" tabindex="-1">1. Handling parse errors <a class="header-anchor" href="#_1-handling-parse-errors" aria-label="Permalink to &quot;1. Handling parse errors&quot;">​</a></h3><p>Godot&#39;s Script Editor reports KonadoScript syntax and semantic problems as you type. Invalid content can still be saved to the <code>.ks</code> source file, but it does not replace the current runtime <code>KonadoShot</code>. Fix the errors and save again to let the resource loader compile it automatically; no manual reimport is required.</p><h3 id="_2-script-file-encoding-issues" tabindex="-1">2. Script file encoding issues <a class="header-anchor" href="#_2-script-file-encoding-issues" aria-label="Permalink to &quot;2. Script file encoding issues&quot;">​</a></h3><p>Make sure the script file is encoded as UTF-8, otherwise garbled text may appear. Script files created by default use UTF-8 encoding.</p><h3 id="_3-protecting-scripts-in-exported-builds" tabindex="-1">3. Protecting scripts in exported builds <a class="header-anchor" href="#_3-protecting-scripts-in-exported-builds" aria-label="Permalink to &quot;3. Protecting scripts in exported builds&quot;">​</a></h3><p>When a project is exported, Konado reads <code>Konado -&gt; Script Encryption Key</code> from the current export preset and automatically encrypts the compiled <code>.ks</code> story data. If the key is empty or malformed, Konado generates a random 256-bit key for the build. Later exports reuse this key unless a developer changes it manually.</p><p>For patches or hot updates, the base build and update must use the same export preset and key. The key is stored in <code>.godot/konado_export_credentials.cfg</code>; back it up separately if it needs to be retained.</p><p>For local exports, the Godot terminal prints the complete build key for developer records and diagnostics. This protection prevents generic extraction tools from reading story text directly from a PCK; it is not dedicated DRM, and targeted analysis of exported resources, client code, or runtime memory may still recover the content.</p>',15)])])}const m=t(i,[["render",s]]);export{h as __pageData,m as default};
